/*=----------------------------------------------------------------------=*\
   Use :Resolves a hostname to an IPv4 address using the configured DNS server. Opens a UDP socket on the specified channel, sends a type-A query, waits up to ~2 seconds for a response, then parses the answer. Returns 1 on success with DNS_ResolvedIP populated, or 0 on timeout or any error.
       :
       :Parameters for macro DNS_GetHostByName:
       :  Channel : UDP socket channel to use (0-3). Must not conflict with DHCP channel.
       :  Hostname[64] : URL to try and resolve e.g. "Flowcode.co.uk"
       :
       :Returns : 1 if the hostname resolved successfully and DNS_ResolvedIP contains the IP, 0 on failure or timeout
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_DNS_GetHostByName(MX_UINT8 FCL_CHANNEL, MX_CHAR *PFCL_HOSTNAME)
{
  //Local variable definitions
  MX_UINT16 FCL_QLEN;
  MX_UINT16 FCL_RLEN;
  MX_UINT16 FCL_TIMEOUT;
  MX_UINT8 FCL_HOSTLEN = (0x0);
  MX_UINT8 FCR_RETVAL; // 1 if the hostname resolved successfully and DNS_ResolvedIP contains the IP, 0 on failure or timeout

  #define FCLsz_HOSTNAME 64
  MX_CHAR FCL_HOSTNAME[FCLsz_HOSTNAME];
  FCI_CONCATENATE(PFCL_HOSTNAME,FCLsz_HOSTNAME,"",0,FCL_HOSTNAME,FCLsz_HOSTNAME);


  // Default to failure
  FCR_RETVAL = 0;

  // Calculation
  FCL_HOSTLEN = FCI_GETLENGTH(FCL_HOSTNAME, FCLsz_HOSTNAME);

  // DNS server configured?
  if (FCV_DNS[0] == 0)
  {  

  } else {

    // Open UDP socket on source port 1025
    FCR_RETVAL = FCM_CreateUDPSocket(FCL_CHANNEL, 1025);

    // Set destination: DNS server port 53
    FCM_SetDestination(FCL_CHANNEL, FCV_DNS[0], FCV_DNS[1], FCV_DNS[2], FCV_DNS[3], 53);

    // Build DNS query into DNS_MSG
    FCL_QLEN = FCM_DNS_BuildQuery(FCL_HOSTNAME, 64, FCL_HOSTLEN);

    // Start transmit
    FCM_TxStart(FCL_CHANNEL);

    // Send DNS query packet
    FCM_TxSendArray(FCL_CHANNEL, FCV_DNS_MSG, 128, FCL_QLEN);

    // End transmit
    FCM_TxEnd(FCL_CHANNEL);

    // Initialise timeout counter
    FCL_TIMEOUT = 0;
    FCL_RLEN = 0;

    // Wait for DNS response (up to ~2 s)
    while ((FCL_RLEN == 0) && (FCL_TIMEOUT < 2000))
    {
      // Poll hardware for incoming data
      FCR_RETVAL = FCM_RxDataAvailable(FCL_CHANNEL);

      // Check for received data
      FCL_RLEN = FCM_RxDataSize(FCL_CHANNEL);

      // Increment timeout counter
      FCL_TIMEOUT = FCL_TIMEOUT + 1;

    }

    // Response received?
    if (FCL_RLEN > 0)
    {    

      // Clamp response length to buffer
      if (FCL_RLEN > 128)
      {      

        // Cap at 128 bytes
        FCL_RLEN = 128;

      // } else {

      }

      // Read response into DNS_MSG buffer
      FCM_RxReadArray(FCL_CHANNEL, FCV_DNS_MSG, 128, FCL_RLEN);

      // Flush remaining receive data
      FCM_RxFlushData(FCL_CHANNEL);

      // Parse DNS response
      FCR_RETVAL = FCM_DNS_ParseResponse(FCL_RLEN);

    } else {

      // Timeout - return failure
      FCR_RETVAL = 0;

    }

    // Close UDP socket
    FCM_TCPClose(FCL_CHANNEL);

  }

  return (FCR_RETVAL);

  //Local variable definitions
  #undef FCLsz_HOSTNAME
}

