/*=----------------------------------------------------------------------=*\
   Use :This macro fills the specified channel's transmit buffer with data.  It can fill the buffer with a string of information.
       :
       :Parameters for macro TxSendString:
       :  Channel : Specifies the communications channel 0-3
       :  Data[20] : Data byte to append to Tx buffer.
       :  Length : Number of characters to transmit
\*=----------------------------------------------------------------------=*/
void FCM_TxSendString(MX_UINT8 FCL_CHANNEL, MX_CHAR *FCL_DATA, MX_UINT16 FCLsz_DATA, MX_UINT8 FCL_LENGTH)
{
  //Local variable definitions
  MX_UINT8 FCL_IDX = (0x0);


  // Call Macro
  FCM_MAC_SetTxBuffer(FCL_CHANNEL);

  // Loop
  while (FCL_IDX < FCL_LENGTH)
  {
    // Add the data to the appropriate place
    FCM_MAC_WriteByte(FCV_GTXPTR[FCL_CHANNEL], FCL_DATA[FCL_IDX]);

    // Increment the pointer and wrap around
    FCV_GTXPTR[FCL_CHANNEL] = FCV_GTXPTR[FCL_CHANNEL] + 1;
    FCV_GTXSIZE[FCL_CHANNEL] = FCV_GTXSIZE[FCL_CHANNEL] + 1;

    // .idx = .idx + 1
    FCL_IDX = FCL_IDX + 1;

  }

}

