/*=----------------------------------------------------------------------=*\
   Use :Internal. Writes a contiguous block of bytes to W5500 registers starting at Address via SPI.
       :
       :Parameters for macro MAC_WriteArray:
       :  Address : W5500 register start address for the write
       :  Data[1000] : Source byte array containing the data to write
       :  Count : Number of bytes to write
\*=----------------------------------------------------------------------=*/
void FCM_MAC_WriteArray(MX_UINT16 FCL_ADDRESS, MX_UINT8 *FCL_DATA, MX_UINT16 FCLsz_DATA, MX_UINT16 FCL_COUNT)
{
  //Local variable definitions
  MX_UINT16 FCL_IDX;


  // Call Component Macro
  FCD_01531_cal_spi__Master_Enable_CS();

  // Write Address High
  FC_CAL_SPI_Master_Byte_1((FCL_ADDRESS & 0xFF00) >> 8);

  // Write Address Low
  FC_CAL_SPI_Master_Byte_1(FCL_ADDRESS & 0xFF);

  // Write Command and Bank
  FC_CAL_SPI_Master_Byte_1(FCV_MAC_BANK | 0x04);

  // Loop
  for (FCL_IDX=0; (FCL_IDX)<(FCL_COUNT); (FCL_IDX)++)
  {
    // Write Data
    FC_CAL_SPI_Master_Byte_1(FCL_DATA[FCL_IDX]);

  }

  // Call Component Macro
  FCD_01531_cal_spi__Master_Disable_CS();

  // Component Macro
  // LibraryComponent1::FlashTx()

}

