/*=----------------------------------------------------------------------=*\
   Use :Note that sockets on up to 4 channels can be simultaneously opened and these channels are numbered 0 to 3.  Note that sockets with different modes can be opened on different channels.
       :
       :Parameters for macro CreateIPSocket:
       :  Channel : Specifies the communications channel 0-3
       :  Protocol : Specifies which IP protocol to use
       :  Broadcast : Allows broadcast type packets to be sent and received
       :
       :Returns : Allocated socket handle (0-3), or 0xFF if no socket was free
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_CreateIPSocket(MX_UINT8 FCL_CHANNEL, MX_UINT8 FCL_PROTOCOL, MX_UINT8 FCL_BROADCAST)
{
  //Local variable definitions
  MX_UINT8 FCL_REGVAL;
  MX_UINT8 FCR_RETVAL; // Allocated socket handle (0-3), or 0xFF if no socket was free


  // Call Macro
  FCM_ModePingBlock(1);

  // Call Macro
  FCM_MAC_SetRegister(FCL_CHANNEL);

  // Call Macro
  FCL_REGVAL = FCM_MAC_ReadByte(FCV_SN_SR);

  // Check if socket is closed
  if (FCL_REGVAL != FCV_SN_SR_CLOSED)
  {  

    // Close Socket
    FCM_MAC_WriteByte(FCV_SN_CR, FCV_SN_CR_CLOSE);

    // Wait for socket to close
    while (FCL_REGVAL != FCV_SN_SR_CLOSED)
    {
      // Call Macro
      FCL_REGVAL = FCM_MAC_ReadByte(FCV_SN_SR);

    }

  // } else {

  }

  // Loop
  while (1)
  {
    //Comment:
    //Sn_MR = 3 is not supported on W5500
    //Some info suggests MACRAW is used 

    // Setup socket protocol and option flags
    FCM_MAC_WriteByte(FCV_SN_MR, FCV_SN_MR_IPRAW | FCV_SN_MR_MFEN | FCV_SN_MR_BCASTB);

    // Setup socket protocol and option flags
    FCM_MAC_WriteByte(FCV_SN_PROTO, FCL_PROTOCOL);

    // Initialise the socket
    FCM_MAC_WriteByte(FCV_SN_CR, FCV_SN_CR_OPEN);

    // Wait until command accepted
    while (1)
    {
      // Read socket status
      FCL_REGVAL = FCM_MAC_ReadByte(FCV_SN_CR);

      if ((FCL_REGVAL) == 0) break;
    }

    // 
    FCL_REGVAL = FCM_MAC_ReadByte(FCV_SN_SR);

    // Delay
    FCI_DELAYBYTE_MS(1);

    if ((FCL_REGVAL == FCV_SN_SR_CLOSED) == 0) break;
  }

  // Reset Globals
  FCV_HEADER[0] = 0;
  FCV_HEADER[1] = 0;
  FCV_HEADER[2] = 0;
  FCV_HEADER[3] = 0;
  FCV_HEADER[4] = 0;
  FCV_HEADER[5] = 0;
  FCV_HEADER[6] = 0;
  FCV_HEADER[7] = 0;

  // Opened socket correctly
  FCR_RETVAL = 1;

  return (FCR_RETVAL);

}

