/*=----------------------------------------------------------------------=*\
   Use :Encodes the given hostname as a DNS type-A query packet into DNS_MSG. Returns the total packet length in bytes.
       :
       :Parameters for macro DNS_BuildQuery:
       :  Hostname[64] : Hostname to resolve as a byte array.
       :  HostLen : Length of the hostname string.
       :
       :Returns : Total length of the DNS query packet in bytes
\*=----------------------------------------------------------------------=*/
MX_UINT16 FCM_DNS_BuildQuery(MX_UINT8 *FCL_HOSTNAME, MX_UINT16 FCLsz_HOSTNAME, MX_UINT8 FCL_HOSTLEN)
{
  //Local variable definitions
  MX_UINT16 FCL_PTR;
  MX_UINT8 FCL_I;
  MX_UINT8 FCL_SEG_START;
  MX_UINT8 FCL_SEG_LEN;
  MX_UINT8 FCL_J;
  MX_UINT16 FCR_RETVAL; // Total length of the DNS query packet in bytes


  // DNS header: ID=0x1234 RD=1 QDCOUNT=1
  FCV_DNS_MSG[0] = 0x12;
  FCV_DNS_MSG[1] = 0x34;
  FCV_DNS_MSG[2] = 0x01;
  FCV_DNS_MSG[3] = 0x00;
  FCV_DNS_MSG[4] = 0x00;
  FCV_DNS_MSG[5] = 0x01;
  FCV_DNS_MSG[6] = 0x00;
  FCV_DNS_MSG[7] = 0x00;
  FCV_DNS_MSG[8] = 0x00;
  FCV_DNS_MSG[9] = 0x00;
  FCV_DNS_MSG[10] = 0x00;
  FCV_DNS_MSG[11] = 0x00;

  // Initialise write pointer and hostname index
  FCL_PTR = 12;
  FCL_I = 0;

  // For each hostname label
  while (FCL_I < FCL_HOSTLEN)
  {
    // Record segment start
    FCL_SEG_START = FCL_I;
    FCL_SEG_LEN = 0;

    // Scan to dot or end
    while ((FCL_I < FCL_HOSTLEN) && (FCL_HOSTNAME[FCL_I] != 46))
    {
      // Advance index and length
      FCL_I = FCL_I + 1;
      FCL_SEG_LEN = FCL_SEG_LEN + 1;

    }

    // Write label length byte and reset inner index
    FCV_DNS_MSG[FCL_PTR] = FCL_SEG_LEN;
    FCL_PTR = FCL_PTR + 1;
    FCL_J = 0;

    // Write label characters
    while (FCL_J < FCL_SEG_LEN)
    {
      // Write character and advance
      FCV_DNS_MSG[FCL_PTR] = FCL_HOSTNAME[FCL_SEG_START + FCL_J];
      FCL_PTR = FCL_PTR + 1;
      FCL_J = FCL_J + 1;

    }

    // Skip dot separator
    if (FCL_I < FCL_HOSTLEN)
    {    

      // Skip the dot character
      FCL_I = FCL_I + 1;

    // } else {

    }

  }

  // Root label, QTYPE=A(1), QCLASS=IN(1)
  FCV_DNS_MSG[FCL_PTR] = 0;
  FCV_DNS_MSG[FCL_PTR + 1] = 0;
  FCV_DNS_MSG[FCL_PTR + 2] = 1;
  FCV_DNS_MSG[FCL_PTR + 3] = 0;
  FCV_DNS_MSG[FCL_PTR + 4] = 1;
  FCL_PTR = FCL_PTR + 5;

  // Return total packet length
  FCR_RETVAL = FCL_PTR;

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Parses a DNS response already loaded into DNS_MSG. On finding a valid TYPE_A answer record sets DNS_ResolvedIP and returns 1, otherwise returns 0.
       :
       :Parameters for macro DNS_ParseResponse:
       :  PktLen : Number of bytes received into DNS_MSG.
       :
       :Returns : 1 if an IPv4 A record was found and DNS_ResolvedIP was populated, 0 otherwise
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_DNS_ParseResponse(MX_UINT16 FCL_PKTLEN)
{
  //Local variable definitions
  MX_UINT16 FCL_PTR;
  MX_UINT16 FCL_ANCOUNT;
  MX_UINT16 FCL_ANS_IDX;
  MX_UINT16 FCL_ANS_TYPE;
  MX_UINT16 FCL_ANS_CLASS;
  MX_UINT16 FCL_RDLEN;
  MX_UINT8 FCL_DONE_FLAG;
  MX_UINT8 FCL_FOUND;
  MX_UINT8 FCR_RETVAL; // 1 if an IPv4 A record was found and DNS_ResolvedIP was populated, 0 otherwise


  // Default to failure
  FCR_RETVAL = 0;

  // Header invalid? (short/wrong ID/not response/RCODE error)
  if ((FCL_PKTLEN < 12) || (FCV_DNS_MSG[0] != 0x12) || (FCV_DNS_MSG[1] != 0x34) || ((FCV_DNS_MSG[2] & 0x80) == 0) || ((FCV_DNS_MSG[3] & 0x0F) != 0))
  {  

  } else {

    // Read answer count
    FCL_ANCOUNT = (FCV_DNS_MSG[6] * 256) + FCV_DNS_MSG[7];

    // No answers?
    if (FCL_ANCOUNT == 0)
    {    

    } else {

      // Start after 12-byte header
      FCL_PTR = 12;

      // Skip QNAME labels (no compression in question)
      while (FCV_DNS_MSG[FCL_PTR] != 0)
      {
        // Skip label: advance by length+1
        FCL_PTR = FCL_PTR + FCV_DNS_MSG[FCL_PTR] + 1;

      }

      // Skip root label, QTYPE, QCLASS (5 bytes)
      FCL_PTR = FCL_PTR + 5;

      // Initialise answer loop
      FCL_ANS_IDX = 0;
      FCL_FOUND = 0;

      // Process each answer record
      while ((FCL_ANS_IDX < FCL_ANCOUNT) && (FCL_FOUND == 0) && (FCL_PTR < FCL_PKTLEN))
      {
        // Reset name-done flag
        FCL_DONE_FLAG = 0;

        // Skip answer NAME (with compression)
        while ((FCV_DNS_MSG[FCL_PTR] != 0) && (FCL_DONE_FLAG == 0))
        {
          // Compression pointer (top 2 bits set)?
          if ((FCV_DNS_MSG[FCL_PTR] & 0xC0) == 0xC0)
          {          

            // Pointer: skip 2 bytes, name ends here
            FCL_PTR = FCL_PTR + 2;
            FCL_DONE_FLAG = 1;

          } else {

            // Normal label: skip length+1
            FCL_PTR = FCL_PTR + FCV_DNS_MSG[FCL_PTR] + 1;

          }

        }

        // Not ended by pointer - skip root 0x00
        if (FCL_DONE_FLAG == 0)
        {        

          // Skip root label byte
          FCL_PTR = FCL_PTR + 1;

        // } else {

        }

        // Read TYPE, CLASS, skip TTL, read RDLENGTH
        FCL_ANS_TYPE = (FCV_DNS_MSG[FCL_PTR] * 256) + FCV_DNS_MSG[FCL_PTR + 1];
        FCL_PTR = FCL_PTR + 2;
        FCL_ANS_CLASS = (FCV_DNS_MSG[FCL_PTR] * 256) + FCV_DNS_MSG[FCL_PTR + 1];
        FCL_PTR = FCL_PTR + 2;
        FCL_PTR = FCL_PTR + 4;
        FCL_RDLEN = (FCV_DNS_MSG[FCL_PTR] * 256) + FCV_DNS_MSG[FCL_PTR + 1];
        FCL_PTR = FCL_PTR + 2;

        // Is this an A record (TYPE=1 CLASS=1)?
        if ((FCL_ANS_TYPE == 1) && (FCL_ANS_CLASS == 1))
        {        

          // Copy 4-byte IP into DNS_ResolvedIP
          FCV_DNS_RESOLVEDIP[0] = FCV_DNS_MSG[FCL_PTR];
          FCV_DNS_RESOLVEDIP[1] = FCV_DNS_MSG[FCL_PTR + 1];
          FCV_DNS_RESOLVEDIP[2] = FCV_DNS_MSG[FCL_PTR + 2];
          FCV_DNS_RESOLVEDIP[3] = FCV_DNS_MSG[FCL_PTR + 3];
          FCL_FOUND = 1;

        } else {

          // Not an A record - skip RDATA
          FCL_PTR = FCL_PTR + FCL_RDLEN;

        }

        // Next answer record
        FCL_ANS_IDX = FCL_ANS_IDX + 1;

      }

      // Return 1 if A record found
      FCR_RETVAL = FCL_FOUND;

    }

  }

  return (FCR_RETVAL);

}

