/*=----------------------------------------------------------------------=*\
   Use :Internal. Writes a single byte to the specified W5500 register address via the SPI bus.
       :
       :Parameters for macro MAC_WriteByte:
       :  Address : W5500 register address to write to
       :  Data : Byte value to write
\*=----------------------------------------------------------------------=*/
void FCM_MAC_WriteByte(MX_UINT16 FCL_ADDRESS, MX_UINT8 FCL_DATA)
{

  // Decision
  if (0)
  {  

    // Call Macro
    FCM_MIAC_Module_PushData(FCL_ADDRESS >> 8);

    // Call Macro
    FCM_MIAC_Module_PushData(FCL_ADDRESS);

    // Call Macro
    FCM_MIAC_Module_PushData(FCL_DATA);

    // Call Macro
    FCM_MIAC_Module_Message((0 << 9) + 64, 801);

  } else {

    // Call Component Macro
    FCD_01531_cal_spi__Master_Enable_CS();

    // Write Address High
    FC_CAL_SPI_Master_Byte_1((FCL_ADDRESS & 0xFF00) >> 8);

    // Write Address Low
    FC_CAL_SPI_Master_Byte_1(FCL_ADDRESS & 0xFF);

    // Write Command and Bank
    FC_CAL_SPI_Master_Byte_1(FCV_MAC_BANK + 4);

    // Write Data
    FC_CAL_SPI_Master_Byte_1(FCL_DATA);

    // Call Component Macro
    FCD_01531_cal_spi__Master_Disable_CS();

  }

  // Component Macro
  // LibraryComponent1::FlashRx()

  // Component Macro
  // LibraryComponent1::FlashTx()

}

/*=----------------------------------------------------------------------=*\
   Use :ForceARP true forces sending ARP Request whenever data is sent
       :
       :Parameters for macro ModeForceARP:
       :  ForceARP : ForceARP true forces sending ARP Request whenever data is sent
\*=----------------------------------------------------------------------=*/
void FCM_ModeForceARP(MX_UINT8 FCL_FORCEARP)
{
  //Local variable definitions
  MX_UINT8 FCL_MR;
  MX_UINT8 FCL_TEMP;


  // Save BANK
  FCL_TEMP = FCV_MAC_BANK;
  FCV_MAC_BANK = 0;

  // Call Macro
  FCL_MR = FCM_MAC_ReadByte(0);

  // Decision
  if (FCL_FORCEARP)
  {  

    // Calculation
    FCL_MR = FCL_MR | 2;

  } else {

    // Calculation
    FCL_MR = FCL_MR & 0xFD;

  }

  // 
  FCM_MAC_WriteByte(0, FCL_MR);

  // Restore BANK
  FCV_MAC_BANK = FCL_TEMP;

}

/*=----------------------------------------------------------------------=*\
   Use :Internal. Builds and broadcasts a DHCPDISCOVER packet on channel 0 (port 67). Appends options: message type=1, client ID (Ethernet/MAC), hostname composed of "WIZnet" and the last three MAC bytes, and a parameter request list asking for subnet mask, gateway, DNS, domain, T1, and T2 timers. Only runs when the DHCP property is enabled. Called automatically by DHCP_Run.
\*=----------------------------------------------------------------------=*/
void FCM_DHCP_Discover()
{

  // Decision
  if (1)
  {  

    // User Macro
    FCM_DHCP_MakeMessage();

    // dhcpMessageType - DISCOVER
    FCV_DHCP_MSG[240] = 53;
    FCV_DHCP_MSG[241] = 1;
    FCV_DHCP_MSG[242] = 1;

    // Client Identifier
    FCV_DHCP_MSG[243] = 61;
    FCV_DHCP_MSG[244] = 7;
    FCV_DHCP_MSG[245] = 1;
    FCV_DHCP_MSG[246] = FCV_MY_MAC[0];
    FCV_DHCP_MSG[247] = FCV_MY_MAC[1];
    FCV_DHCP_MSG[248] = FCV_MY_MAC[2];
    FCV_DHCP_MSG[249] = FCV_MY_MAC[3];
    FCV_DHCP_MSG[250] = FCV_MY_MAC[4];
    FCV_DHCP_MSG[251] = FCV_MY_MAC[5];

    // HostName
    FCV_DHCP_MSG[252] = 12;
    FCV_DHCP_MSG[253] = 9;
    FCV_DHCP_MSG[254] = 'W';
    FCV_DHCP_MSG[255] = 'I';
    FCV_DHCP_MSG[256] = 'Z';
    FCV_DHCP_MSG[257] = 'n';
    FCV_DHCP_MSG[258] = 'e';
    FCV_DHCP_MSG[259] = 't';
    FCV_DHCP_MSG[260] = FCV_MY_MAC[3];
    FCV_DHCP_MSG[261] = FCV_MY_MAC[4];
    FCV_DHCP_MSG[262] = FCV_MY_MAC[5];

    // Options
    FCV_DHCP_MSG[263] = 55;
    FCV_DHCP_MSG[264] = 6;
    FCV_DHCP_MSG[265] = 1;
    FCV_DHCP_MSG[266] = 3;
    FCV_DHCP_MSG[267] = 6;
    FCV_DHCP_MSG[268] = 15;
    FCV_DHCP_MSG[269] = 58;
    FCV_DHCP_MSG[270] = 59;
    FCV_DHCP_MSG[271] = 255;

    // Setup broadcast packet
    FCM_SetDestination(0, 255, 255, 255, 255, 67);

    // User Macro
    FCM_TxStart(0);

    // endOption
    FCM_TxSendArray(0, FCV_DHCP_MSG, 548, 272);

    // User Macro
    FCM_TxEnd(0);

  // } else {

  }

}

