/*=----------------------------------------------------------------------=*\
   Use :Formats one of the DHCP-assigned network addresses as a null-terminated dotted-decimal ASCII string (e.g. "192.168.1.100") and writes it into Output. Selection: 0=assigned IP, 1=subnet mask, 2=gateway, 3=DNS server. Output must be at least 16 bytes.
       :
       :Parameters for macro GetIPString:
       :  Selection : Which address: 0=IP, 1=Subnet, 2=Gateway, 3=DNS
       :  Output[16] : Caller-supplied buffer of at least 16 bytes; receives the formatted string
\*=----------------------------------------------------------------------=*/
void FCM_GetIPString(MX_UINT8 FCL_SELECTION, MX_CHAR *FCL_OUTPUT, MX_UINT16 FCLsz_OUTPUT)
{
  //Local variable definitions
  MX_UINT8 FCL_B0 = (0x0);
  MX_UINT8 FCL_B1 = (0x0);
  MX_UINT8 FCL_B2 = (0x0);
  MX_UINT8 FCL_B3 = (0x0);


  // Default source DNS
  FCL_B0 = FCV_DNS[0];
  FCL_B1 = FCV_DNS[1];
  FCL_B2 = FCV_DNS[2];
  FCL_B3 = FCV_DNS[3];

  // Decision
  if (FCL_SELECTION == 0)
  {  

    // Copy assigned IP
    FCL_B0 = FCV_MY_IP[0];
    FCL_B1 = FCV_MY_IP[1];
    FCL_B2 = FCV_MY_IP[2];
    FCL_B3 = FCV_MY_IP[3];

  // } else {

  }

  // Decision
  if (FCL_SELECTION == 1)
  {  

    // Copy subnet mask
    FCL_B0 = FCV_SUBNET[0];
    FCL_B1 = FCV_SUBNET[1];
    FCL_B2 = FCV_SUBNET[2];
    FCL_B3 = FCV_SUBNET[3];

  // } else {

  }

  // Decision
  if (FCL_SELECTION == 2)
  {  

    // Copy gateway
    FCL_B0 = FCV_GATEWAY[0];
    FCL_B1 = FCV_GATEWAY[1];
    FCL_B2 = FCV_GATEWAY[2];
    FCL_B3 = FCV_GATEWAY[3];

  // } else {

  }

  // Calculation
  {
  MX_CHAR FCI_TMP_STR[MX_MAX_TMPSTR_SIZE];
  MX_CHAR FCI_TMP1_STR[MX_MAX_TMPSTR_SIZE];
  FCI_SHEAD(FCI_TOSTRING(FCL_B0, FCI_TMP1_STR,MX_MAX_TMPSTR_SIZE),20, ".",2, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCI_TOSTRING(FCL_B1, FCI_TMP1_STR,MX_MAX_TMPSTR_SIZE),20, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, ".",2, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCI_TOSTRING(FCL_B2, FCI_TMP1_STR,MX_MAX_TMPSTR_SIZE),20, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, ".",2, FCI_TMP_STR,MX_MAX_TMPSTR_SIZE);
  FCI_SHEAD(FCI_TMP_STR,MX_MAX_TMPSTR_SIZE, FCI_TOSTRING(FCL_B3, FCI_TMP1_STR,MX_MAX_TMPSTR_SIZE),20, FCL_OUTPUT,16);
  }

}

