/*=----------------------------------------------------------------------=*\
   Use :Internal. Reads a single byte from the specified W5500 register address via the SPI bus.
       :
       :Parameters for macro MAC_ReadByte:
       :  Address : W5500 register address to read from
       :
       :Returns : Byte read from the W5500 register
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_MAC_ReadByte(MX_UINT16 FCL_ADDRESS)
{
  //Local variable definitions
  MX_UINT8 FCL_RET;
  MX_UINT8 FCR_RETVAL; // Byte read from the W5500 register


  // Decision
  if (0)
  {  

    // Call Macro
    FCM_MIAC_Module_PushData(FCL_ADDRESS >> 8);

    // Call Macro
    FCM_MIAC_Module_PushData(FCL_ADDRESS);

    // Call Macro
    FCL_RET = FCM_MIAC_Module_Message((0 << 9) + 64, 802);

    // Call Macro
    FCR_RETVAL = FCM_MIAC_Module_GetData(0);

  } else {

    // Call Component Macro
    FCD_01531_cal_spi__Master_Enable_CS();

    // Write Address High
    FC_CAL_SPI_Master_Byte_1((FCL_ADDRESS & 0xFF00) >> 8);

    // Write Address Low
    FC_CAL_SPI_Master_Byte_1(FCL_ADDRESS & 0xFF);

    // Write Command and Bank
    FC_CAL_SPI_Master_Byte_1(FCV_MAC_BANK);

    // Write Data
    FCR_RETVAL = FC_CAL_SPI_Master_Byte_1(0xAA);

    // Call Component Macro
    FCD_01531_cal_spi__Master_Disable_CS();

  }

  // Component Macro
  // LibraryComponent1::FlashRx()

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Once data reception has been completed, this macro should be called to discard the data packet and allow other data packets to be read.
       :
       :Parameters for macro RxFlushData:
       :  Channel : Specifies the communications channel 0-3
\*=----------------------------------------------------------------------=*/
void FCM_RxFlushData(MX_UINT8 FCL_CHANNEL)
{
  //Local variable definitions
  MX_UINT16 FCL_RX_SZ;
  MX_UINT16 FCL_RX_PTR;


  // Call Macro
  FCM_MAC_SetRegister(FCL_CHANNEL);

  // Get the received size
  FCL_RX_SZ = FCM_MAC_ReadWord(FCV_SN_RX_RSR);

  // Decision
  if (FCL_RX_SZ)
  {  

    // Call Macro
    FCL_RX_PTR = FCM_MAC_ReadWord(FCV_SN_RX_RD);

    // Calculation
    FCL_RX_PTR = (FCL_RX_PTR + FCL_RX_SZ);

    // Call Macro
    FCM_MAC_WriteWord(FCV_SN_RX_RD, FCL_RX_PTR);

    // Send the RECV command
    FCM_MAC_WriteByte(FCV_SN_CR, FCV_SN_CR_RECV);

  // } else {

  }

}

