/*=----------------------------------------------------------------------=*\
   Use :Advances the DHCP state machine by one step and returns 0. States: 0=send DISCOVER; 1=wait for OFFER (type 2), timeout on miss; 2=wait for ACK (type 5) then advance to state 3 (leased); 3=leased, no-op (DHCP_CheckLease handles renewal); 4=renewal REQUEST sent, advance to 5; 5=wait for renewal ACK (type 5) or NAK/timeout back to 0. Called automatically by Initialise during startup. To force renegotiation: set DHCP_State=0, DHCP_Timeout=0, then call this macro in a polling loop until DHCP_State reaches 3 or DHCP_Timeout exceeds 1000.
       :
       :Returns : Always 0; the DHCP lease state is tracked in DHCP_State
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_DHCP_Run()
{
  //Local variable definitions
  MX_UINT8 FCL_TYPE;
  MX_UINT8 FCR_RETVAL; // Always 0; the DHCP lease state is tracked in DHCP_State


  // Calculation
  FCR_RETVAL = 0;

  // User Macro
  FCL_TYPE = FCM_DHCP_Parse();

  // Switch
  switch (FCV_DHCP_STATE)
  {
    case 1:
    {

      //Comment:
      //Discover

      // DHCP Offer?
      if (FCL_TYPE == 2)
      {      

        // User Macro
        FCM_DHCP_Request();

        // Request Stage
        FCV_DHCP_STATE = 2;

      } else {

        // Delay
        FCI_DELAYBYTE_MS(1);

        // Calculation
        FCV_DHCP_TIMEOUT = FCV_DHCP_TIMEOUT + 1;

      }

      break;
    }
    case 2:
    {

      //Comment:
      //Request

      // Decision
      if (FCL_TYPE == 5)
      {      

        // Request Stage
        FCV_DHCP_STATE = 3;

      } else {

        // Delay
        FCI_DELAYBYTE_MS(1);

        // Calculation
        FCV_DHCP_TIMEOUT = FCV_DHCP_TIMEOUT + 1;

      }

      break;
    }
    case 3:
    {

      // Calculation


      break;
    }
    case 4:
    {

      //Comment:
      //Renewal: send unicast REQUEST to DHCP server

      // User Macro
      FCM_DHCP_Request();

      // Advance to wait-for-ACK state
      FCV_DHCP_STATE = 5;

      break;
    }
    case 5:
    {

      //Comment:
      //Waiting for renewal ACK

      // ACK received?
      if (FCL_TYPE == 5)
      {      

        // Renewal success: reset countdown from new lease time
        FCV_DHCP_RENEWIN = FCV_DHCP_LEASETIME >> 1;
        FCV_DHCP_STATE = 3;

      } else {

        // NAK received?
        if (FCL_TYPE == 6)
        {        

          // NAK: fall back to full discovery
          FCV_DHCP_STATE = 0;

        } else {

          // Still waiting
          FCV_DHCP_TIMEOUT = FCV_DHCP_TIMEOUT + 1;

        }

      }

      break;
    }
    case 6:
    {

      break;
    }
    case 7:
    {

      break;
    }
    case 8:
    {

      break;
    }
    default:
    {
      //Comment:
      //Init

      // Open DHCP socket on port 68
      FCR_RETVAL = FCM_CreateUDPSocket(0, 68);

      // User Macro
      FCM_DHCP_Discover();

      // Discover Stage
      FCV_DHCP_STATE = 1;

    }
  }

  return (FCR_RETVAL);

}

/*=----------------------------------------------------------------------=*\
   Use :Call once per second from your main loop when DHCP is enabled. Decrements the T1 renewal timer and when it expires attempts a unicast renewal, falling back to full rediscovery if the renewal fails. Returns: 0=lease OK, 2=renewed, 3=rebind failed, 4=rebind succeeded.
       :
       :Returns : 0=OK, 2=renewed, 3=rebind failed, 4=rebind succeeded
\*=----------------------------------------------------------------------=*/
MX_UINT8 FCM_DHCP_CheckLease()
{
  //Local variable definitions
  MX_UINT8 FCR_RETVAL; // 0=OK, 2=renewed, 3=rebind failed, 4=rebind succeeded


  // Calculation
  FCR_RETVAL = 0;

  // DHCP enabled and lease active?
  if (1 && (FCV_DHCP_STATE == 3))
  {  

    // Time remaining before T1?
    if (FCV_DHCP_RENEWIN > 0)
    {    

      // Decrement renewal countdown
      FCV_DHCP_RENEWIN = FCV_DHCP_RENEWIN - 1;

    } else {

      // T1 expired: attempt unicast renewal
      FCV_DHCP_STATE = 4;
      FCV_DHCP_TIMEOUT = 0;

      // Loop
      while ((FCV_DHCP_TIMEOUT < 500) && (FCV_DHCP_STATE < 3))
      {
        // User Macro
        FCM_DHCP_Run();

      }

      // Renewal succeeded?
      if (FCV_DHCP_STATE == 3)
      {      

        // Calculation
        FCR_RETVAL = 2;

      } else {

        // Renewal failed: fall back to full rediscovery (rebind)
        FCV_DHCP_STATE = 0;
        FCV_DHCP_TIMEOUT = 0;

        // Loop
        while ((FCV_DHCP_TIMEOUT < 1000) && (FCV_DHCP_STATE < 3))
        {
          // User Macro
          FCM_DHCP_Run();

        }

        // Rebind succeeded?
        if (FCV_DHCP_STATE == 3)
        {        

          // Set Gateway
          FCM_MAC_WriteArray(0x01, FCV_GATEWAY, 4, 4);

          // Set Subnet
          FCM_MAC_WriteArray(0x05, FCV_SUBNET, 4, 4);

          // Set IP Address
          FCM_MAC_WriteArray(0x0F, FCV_MY_IP, 4, 4);

          // Calculation
          FCR_RETVAL = 4;

        } else {

          // Calculation
          FCR_RETVAL = 3;

        }

      }

    }

  // } else {

  }

  return (FCR_RETVAL);

}

