/*=----------------------------------------------------------------------=*\
   Use :Internal. Builds and sends a DHCPREQUEST on channel 0. For lease renewal (DHCP_State=4) unicasts to DHCP_ServerIP with ciaddr set to the current My_IP (as required by RFC 2131 for unicast renewal). For initial requests (all other states) broadcasts to 255.255.255.255. Appends TLV options: message type=3, client ID, requested IP, server identifier, parameter request list, END. Called automatically by DHCP_Run.
\*=----------------------------------------------------------------------=*/
void FCM_DHCP_Request()
{
  //Local variable definitions
  MX_UINT8 FCL_IDX;
  MX_UINT16 FCL_PTR;
  #define FCLsz_IP 4
  MX_UINT8 FCL_IP[FCLsz_IP];


  // Decision
  if (1)
  {  

    // User Macro
    FCM_DHCP_MakeMessage();

    // Renewal (state 4) or initial request?
    if (FCV_DHCP_STATE == 4)
    {    

      // Renewal: unicast to DHCP server
      FCL_IP[0] = FCV_DHCP_SERVERIP[0];
      FCL_IP[1] = FCV_DHCP_SERVERIP[1];
      FCL_IP[2] = FCV_DHCP_SERVERIP[2];
      FCL_IP[3] = FCV_DHCP_SERVERIP[3];

      // Set ciaddr to current IP (required for unicast renewal)
      FCV_DHCP_MSG[12] = FCV_MY_IP[0];
      FCV_DHCP_MSG[13] = FCV_MY_IP[1];
      FCV_DHCP_MSG[14] = FCV_MY_IP[2];
      FCV_DHCP_MSG[15] = FCV_MY_IP[3];

    } else {

      // Initial request: broadcast
      FCL_IP[0] = 255;
      FCL_IP[1] = 255;
      FCL_IP[2] = 255;
      FCL_IP[3] = 255;

    }

    // dhcpMessageType - REQUEST
    FCV_DHCP_MSG[240] = 53;
    FCV_DHCP_MSG[241] = 1;
    FCV_DHCP_MSG[242] = 2;

    // Client Identifier
    FCV_DHCP_MSG[243] = 61;
    FCV_DHCP_MSG[244] = 7;
    FCV_DHCP_MSG[245] = 1;
    FCV_DHCP_MSG[246] = FCV_MY_MAC[0];
    FCV_DHCP_MSG[247] = FCV_MY_MAC[1];
    FCV_DHCP_MSG[248] = FCV_MY_MAC[2];
    FCV_DHCP_MSG[249] = FCV_MY_MAC[3];
    FCV_DHCP_MSG[250] = FCV_MY_MAC[4];
    FCV_DHCP_MSG[251] = FCV_MY_MAC[5];

    // HostName
    FCV_DHCP_MSG[252] = 12;
    FCV_DHCP_MSG[253] = 9;
    FCV_DHCP_MSG[254] = 'W';
    FCV_DHCP_MSG[255] = 'I';
    FCV_DHCP_MSG[256] = 'Z';
    FCV_DHCP_MSG[257] = 'n';
    FCV_DHCP_MSG[258] = 'e';
    FCV_DHCP_MSG[259] = 't';
    FCV_DHCP_MSG[260] = FCV_MY_MAC[3];
    FCV_DHCP_MSG[261] = FCV_MY_MAC[4];
    FCV_DHCP_MSG[262] = FCV_MY_MAC[5];

    // Options
    FCV_DHCP_MSG[263] = 55;
    FCV_DHCP_MSG[264] = 8;
    FCV_DHCP_MSG[265] = 1;
    FCV_DHCP_MSG[266] = 3;
    FCV_DHCP_MSG[267] = 6;
    FCV_DHCP_MSG[268] = 15;
    FCV_DHCP_MSG[269] = 58;
    FCV_DHCP_MSG[270] = 59;
    FCV_DHCP_MSG[271] = 31;
    FCV_DHCP_MSG[272] = 33;
    FCV_DHCP_MSG[273] = 255;

    // Setup broadcast packet
    FCM_SetDestination(0, FCL_IP[0], FCL_IP[1], FCL_IP[2], FCL_IP[3], 67);

    // User Macro
    FCM_TxStart(0);

    // endOption
    FCM_TxSendArray(0, FCV_DHCP_MSG, 548, 274);

    // User Macro
    FCM_TxEnd(0);

  // } else {

  }

  //Local variable definitions
  #undef FCLsz_IP
}

