/*=----------------------------------------------------------------------=*\
   Use :Internal. Writes a 16-bit value to two consecutive W5500 register bytes in big-endian order (high byte first).
       :
       :Parameters for macro MAC_WriteWord:
       :  Address : W5500 register address of the first (high) byte to write
       :  Data : 16-bit value to write, transmitted big-endian (high byte first)
\*=----------------------------------------------------------------------=*/
void FCM_MAC_WriteWord(MX_UINT16 FCL_ADDRESS, MX_UINT16 FCL_DATA)
{

  // Decision
  if (0)
  {  

    // Call Macro
    FCM_MIAC_Module_SetData(4, FCL_ADDRESS >> 8, FCL_ADDRESS, FCL_DATA >> 8, FCL_DATA, 0, 0);

    // Call Macro
    FCM_MIAC_Module_Message((0 << 9) + 64, 803);

  } else {

    // Call Component Macro
    FCD_01531_cal_spi__Master_Enable_CS();

    // Write Address High
    FC_CAL_SPI_Master_Byte_1((FCL_ADDRESS & 0xFF00) >> 8);

    // Write Address Low
    FC_CAL_SPI_Master_Byte_1(FCL_ADDRESS & 0xFF);

    // Write Command and Bank
    FC_CAL_SPI_Master_Byte_1(FCV_MAC_BANK + 4);

    // Write Data
    FC_CAL_SPI_Master_Byte_1((FCL_DATA & 0xFF00) >> 8);

    // Write Data
    FC_CAL_SPI_Master_Byte_1(FCL_DATA & 0x00FF);

    // Call Component Macro
    FCD_01531_cal_spi__Master_Disable_CS();

  }

  // Component Macro
  // LibraryComponent1::FlashRx()

  // Component Macro
  // LibraryComponent1::FlashTx()

}

/*=----------------------------------------------------------------------=*\
   Use :This macro fills the specified channel's transmit buffer with data.
       :
       :Parameters for macro TxSendArray:
       :  Channel : Specifies the communications channel 0-3
       :  Data[1000] : Data byte to append to Tx buffer.
       :  Count : Number of bytes to transmit
\*=----------------------------------------------------------------------=*/
void FCM_TxSendArray(MX_UINT8 FCL_CHANNEL, MX_UINT8 *FCL_DATA, MX_UINT16 FCLsz_DATA, MX_UINT16 FCL_COUNT)
{

  // Call Macro
  FCM_MAC_SetTxBuffer(FCL_CHANNEL);

  // Add the data to the appropriate place
  FCM_MAC_WriteArray(FCV_GTXPTR[FCL_CHANNEL], FCL_DATA, 1000, FCL_COUNT);

  // Increment the pointer and wrap around
  FCV_GTXPTR[FCL_CHANNEL] = FCV_GTXPTR[FCL_CHANNEL] + FCL_COUNT;
  FCV_GTXSIZE[FCL_CHANNEL] = FCV_GTXSIZE[FCL_CHANNEL] + FCL_COUNT;

}

