/*=----------------------------------------------------------------------=*\
   Use :When an established TCP connection has finished transmission of data, either the local application (i.e. your code) or the remote application (i.e. the application at the other end of the connection) can initiate closure of the socket.
       :
       :Parameters for macro TCPClose:
       :  Channel : Specifies the communications channel 0-3
\*=----------------------------------------------------------------------=*/
void FCM_TCPClose(MX_UINT8 FCL_CHANNEL)
{
  //Local variable definitions
  MX_UINT8 FCL_IS_EQUAL = (0x0);
  MX_UINT8 FCL_TIMEOUT = (0x64);
  MX_UINT8 FCL_TEMP;


  // Call Macro
  FCM_MAC_SetRegister(FCL_CHANNEL);

  // Loop
  while (FCL_IS_EQUAL == 0)
  {
    // Call Macro
    FCL_TEMP = FCM_MAC_ReadByte(FCV_SN_IR);

    // Decision
    if (FCL_TEMP & 0x10)
    {    

      // Calculation
      FCL_IS_EQUAL = 1;

    } else {

      // Delay
      FCI_DELAYBYTE_MS(1);

      // Calculation
      FCL_TIMEOUT = FCL_TIMEOUT - 1;

      // Decision
      if (FCL_TIMEOUT == 0)
      {      

        // Calculation
        FCL_IS_EQUAL = 1;

      // } else {

      }

    }

  }

  // Has there been a timeout?
  if (FCL_TIMEOUT != 0)
  {  

    // Not timed out so ok to close
    FCM_MAC_WriteByte(FCV_SN_CR, FCV_SN_CR_DISCON);

    // Calculation
    FCL_IS_EQUAL = 1;

    // Loop
    while (FCL_IS_EQUAL)
    {
      // Call Macro
      FCL_IS_EQUAL = FCM_MAC_ReadByte(FCV_SN_CR);

    }

    // Disconnected, now close
    FCM_MAC_WriteByte(FCV_SN_CR, FCV_SN_CR_CLOSE);

    // Calculation
    FCL_IS_EQUAL = 1;

    // Loop
    while (FCL_IS_EQUAL)
    {
      // Call Macro
      FCL_IS_EQUAL = FCM_MAC_ReadByte(FCV_SN_CR);

    }

  // } else {

  }

}

