/*=----------------------------------------------------------------------=*\
   Use :Internal. Fills DHCP_MSG[0..239] with the standard 236-byte BOOTP/DHCP fixed header: op=BOOTREQUEST(1), htype=Ethernet(1), hlen=6, hops=0, xid=0x12345678, secs=0, flags=BROADCAST(0x8000), ciaddr/yiaddr/siaddr/giaddr=0, chaddr=My_MAC (zero-padded to 16 bytes, server/file fields zeroed). Appends the DHCP magic cookie (0x63825363) at bytes 236-239. DHCP_Discover and DHCP_Request call this first, then append their option TLVs from offset 240.
\*=----------------------------------------------------------------------=*/
void FCM_DHCP_MakeMessage()
{
  //Local variable definitions
  MX_UINT16 FCL_IDX;
  MX_UINT16 FCL_PTR;


  // Decision
  if (1)
  {  

    // Calculation
    FCV_DHCP_MSG[0] = 1;
    FCV_DHCP_MSG[1] = 1;
    FCV_DHCP_MSG[2] = 6;
    FCV_DHCP_MSG[3] = 0;
    FCV_DHCP_MSG[4] = 0x12;
    FCV_DHCP_MSG[5] = 0x34;
    FCV_DHCP_MSG[6] = 0x56;
    FCV_DHCP_MSG[7] = 0x78;
    FCV_DHCP_MSG[8] = 0x00;
    FCV_DHCP_MSG[9] = 0x00;
    FCV_DHCP_MSG[10] = 0x80;
    FCV_DHCP_MSG[11] = 0x00;
    FCV_DHCP_MSG[12] = 0;
    FCV_DHCP_MSG[13] = 0;
    FCV_DHCP_MSG[14] = 0;
    FCV_DHCP_MSG[15] = 0;
    FCV_DHCP_MSG[16] = 0;
    FCV_DHCP_MSG[17] = 0;
    FCV_DHCP_MSG[18] = 0;
    FCV_DHCP_MSG[19] = 0;
    FCV_DHCP_MSG[20] = 0;
    FCV_DHCP_MSG[21] = 0;
    FCV_DHCP_MSG[22] = 0;
    FCV_DHCP_MSG[23] = 0;
    FCV_DHCP_MSG[24] = 0;
    FCV_DHCP_MSG[25] = 0;
    FCV_DHCP_MSG[26] = 0;
    FCV_DHCP_MSG[27] = 0;
    FCV_DHCP_MSG[28] = FCV_MY_MAC[0];
    FCV_DHCP_MSG[29] = FCV_MY_MAC[1];
    FCV_DHCP_MSG[30] = FCV_MY_MAC[2];
    FCV_DHCP_MSG[31] = FCV_MY_MAC[3];
    FCV_DHCP_MSG[32] = FCV_MY_MAC[4];
    FCV_DHCP_MSG[33] = FCV_MY_MAC[5];
    FCV_DHCP_MSG[34] = 0;
    FCV_DHCP_MSG[35] = 0;
    FCV_DHCP_MSG[36] = 0;
    FCV_DHCP_MSG[37] = 0;
    FCV_DHCP_MSG[38] = 0;
    FCV_DHCP_MSG[39] = 0;
    FCV_DHCP_MSG[40] = 0;
    FCV_DHCP_MSG[41] = 0;
    FCV_DHCP_MSG[42] = 0;
    FCV_DHCP_MSG[43] = 0;

    // Calculation
    FCL_PTR = 44;

    // Loop
    for (FCL_IDX=0; (FCL_IDX)<(64); (FCL_IDX)++)
    {
      // sname
      FCV_DHCP_MSG[FCL_PTR] = 0;
      FCL_PTR = FCL_PTR + 1;

    }

    // Loop
    for (FCL_IDX=0; (FCL_IDX)<(128); (FCL_IDX)++)
    {
      // file
      FCV_DHCP_MSG[FCL_PTR] = 0;
      FCL_PTR = FCL_PTR + 1;

    }

    // //opt
    FCV_DHCP_MSG[236] = 0x63;
    FCV_DHCP_MSG[237] = 0x82;
    FCV_DHCP_MSG[238] = 0x53;
    FCV_DHCP_MSG[239] = 0x63;

  // } else {

  }

}

